1. /* global DEPLOYMENT_VERSION */
2. import 'core/polyfill';
3. import { oneLine } from 'common-tags';
4. import config from 'config';
5. import FastClick from 'fastclick';
6. import { createBrowserHistory } from 'history';
7. import RavenJs from 'raven-js';
8. import * as React from 'react';
9. import { render } from 'react-dom';
10. import { loadableReady } from '@loadable/component';
11. 
12. import Root from 'core/components/Root';
13. import { langToLocale, makeI18n, sanitizeLanguage } from 'core/i18n/utils';
14. import log from 'core/logger';
15. import { addQueryParamsToHistory } from 'core/utils';
16. import { getSentryRelease } from 'core/utils/sentry';
17. import tracking from 'core/tracking';
18. 
19. export default async function createClient(
20.   createStore,
21.   {
22.     _FastClick = FastClick,
23.     _RavenJs = RavenJs,
24.     _config = config,
25.     _createBrowserHistory = createBrowserHistory,
26.     _tracking = tracking,
27.     sagas = null,
28.   } = {},
29. ) {
30.   if (_config.get('isDevelopment')) {
31.     // eslint-disable-next-line global-require, import/no-extraneous-dependencies
32.     const { fetchBufferedLogs } = require('pino-devtools/src/client');
33.     await fetchBufferedLogs();
34.   }
35. 
36.   const appName = _config.get('appName');
37. 
38.   // This code needs to come before anything else so we get logs/errors if
39.   // anything else in this function goes wrong.
40.   const publicSentryDsn = _config.get('publicSentryDsn');
41.   const sentryIsEnabled = Boolean(publicSentryDsn);
42.   if (sentryIsEnabled) {
43.     log.info(`Configured client-side Sentry with DSN ${publicSentryDsn}`);
44.     _RavenJs
45.       .config(publicSentryDsn, {
46.         logger: 'client-js',
47.         // `DEPLOYMENT_VERSION` is injected by webpack at build time (thanks to
48.         // the `DefinePlugin`).
49.         // See: https://github.com/mozilla/addons-frontend/issues/8270
50.         release: getSentryRelease({ appName, version: DEPLOYMENT_VERSION }),
51.       })
52.       .install();
53.   } else {
54.     log.warn('Client-side Sentry reporting was disabled by the config');
55.   }
56. 
57.   if (config.get('enableStrictMode')) {
58.     log.info(oneLine`StrictMode is enabled, which causes double redux action
59.       dispatching. See: https://github.com/mozilla/addons-frontend/issues/6424`);
60.   }
61. 
62.   _FastClick.attach(document.body);
63. 
64.   const initialStateContainer = document.getElementById('redux-store-state');
65.   let initialState;
66. 
67.   const html = document.querySelector('html');
68.   const lang = sanitizeLanguage(html.getAttribute('lang'));
69.   const locale = langToLocale(lang);
70. 
71.   if (initialStateContainer) {
72.     try {
73.       initialState = JSON.parse(initialStateContainer.textContent);
74.     } catch (error) {
75.       log.error('Could not load initial redux data');
76.     }
77.   }
78. 
79.   const history = addQueryParamsToHistory({
80.     history: _createBrowserHistory({
81.       // When `forceRefresh` is `true`, client side navigation is disabled and
82.       // all links will trigger a full page reload. This is what we want when
83.       // the server has loaded an anoynmous page.
84.       //
85.       // Note: we check the presence of the `site` state because the `disco`
86.       // app uses the same code but does not use this state.
87.       forceRefresh:
88.         initialState && initialState.site
89.           ? initialState.site.loadedPageIsAnonymous
90.           : false,
91.     }),
92.   });
93. 
94.   // See: https://github.com/mozilla/addons-frontend/issues/8647
95.   history.listen((location) => {
96.     _tracking.setPage(location.pathname);
97.     // It is guaranteed that the navigation has happened but the title of the
98.     // page is likely stale, so we are omitting it.
99.     _tracking.pageView({ title: '' });
100.   });
101. 
102.   const { sagaMiddleware, store } = createStore({ history, initialState });
103. 
104.   if (sentryIsEnabled) {
105.     _RavenJs.setTagsContext({ amo_request_id: store.getState().api.requestId });
106.   }
107. 
108.   if (sagas && sagaMiddleware) {
109.     sagaMiddleware.run(sagas);
110.   } else {
111.     log.warn(`sagas not found for this app (src/${appName}/sagas)`);
112.   }
113. 
114.   let i18nData = {};
115.   try {
116.     if (locale !== langToLocale(_config.get('defaultLang'))) {
117.       i18nData = await new Promise((resolve) => {
118.         // eslint-disable-next-line max-len, global-require, import/no-dynamic-require
119.         require(`bundle-loader?name=[name]-i18n-[folder]!../../locale/${locale}/${appName}.js`)(
120.           resolve,
121.         );
122.       });
123.     }
124.   } catch (e) {
125.     log.info(oneLine`Locale not found or required for locale: "${locale}".
126.       Falling back to default lang: "${_config.get('defaultLang')}"`);
127.   }
