31.     htmlDir: LTR,
32.     htmlLang: 'en-US',
33.     trackingEnabled: false,
34.     _config: config,
35.   };
36. 
37.   getSriProps(assetName) {
38.     const { includeSri, sriData } = this.props;
39. 
