58.     const { appName } = this.props;
59.     const leafName = filePath.split('/').pop();
60. 
61.     // Only output files for the current app.
62.     if (leafName.startsWith(appName) && !JS_CHUNK_EXCLUDES.test(leafName)) {
63.       const sriProps = this.getSriProps(leafName);
64. 
65.       switch (type) {
66.         case 'css':
67.           return (
68.             <link
69.               href={filePath}
70.               {...sriProps}
71.               key={type + index}
72.               rel="stylesheet"
73.               type="text/css"
74.             />
75.           );
76.         case 'js':
77.           return <script key={type + index} src={filePath} {...sriProps} />;
78.         default:
79.           throw new Error('Unknown static type');
80.       }
81.     } else {
82.       return null;
83.     }
84.   }
