96.     const { assets } = this.props;
97.     return Object.keys(assets.styles).map((style, index) =>
98.       this.getStatic({ filePath: assets.styles[style], type: 'css', index }),
99.     );
100.   }
101. 
102.   getScript() {
103.     const { assets } = this.props;
104.     return Object.keys(assets.javascript).map((js, index) =>
105.       this.getStatic({ filePath: assets.javascript[js], type: 'js', index }),
106.     );
107.   }
108. 
109.   getFaviconLink() {
110.     const { _config } = this.props;
111.     return `${_config.get('amoCDN')}/favicon.ico?v=${_config.get(
112.       'faviconVersion',
113.     )}`;
114.   }
115. 
116.   renderStyles() {
117.     const { _config, chunkExtractor } = this.props;
118. 
119.     return chunkExtractor
120.       .getMainAssets('style')
121.       .filter(
122.         // We render the main bundle with `getScript()`, so we skip it here.
123.         (asset) => !_config.get('validAppNames').includes(asset.chunk),
124.       )
125.       .map((asset) => {
126.         const sriProps = this.getSriProps(asset.filename);
127. 
128.         return (
129.           <link
130.             data-chunk={asset.chunk}
131.             href={asset.url}
132.             key={asset.url}
133.             rel="stylesheet"
134.             type="text/css"
135.             {...sriProps}
136.           />
137.         );
138.       });
139.   }
140. 
141.   renderPreLinks() {
142.     const { chunkExtractor } = this.props;
143. 
144.     return (
145.       chunkExtractor
146.         .getPreAssets()
147.         // We want to retrieve the bundles with "webpackPreload: true" only, and
148.         // not the main bundle (amo or disco).
149.         .filter((asset) => asset.type === 'childAsset')
150.         // We return both "preload" and "prefetch" links to maximize browser
151.         // support, even though both links don't have the same goal.
152.         .map((asset) => [
153.           <link
154.             as={asset.scriptType}
155.             data-parent-chunk={asset.chunk}
156.             href={asset.url}
157.             key={`preload-${asset.url}`}
158.             rel="preload"
159.           />,
160.           <link
161.             as={asset.scriptType}
162.             data-parent-chunk={asset.chunk}
163.             href={asset.url}
164.             key={`prefetch-${asset.url}`}
165.             rel="prefetch"
166.           />,
167.         ])
168.     );
169.   }
170. 
171.   renderAsyncScripts() {
172.     const { _config, chunkExtractor } = this.props;
173. 
174.     return chunkExtractor
175.       .getMainAssets('script')
176.       .filter(
177.         // We render the main bundle with `getScript()`, so we skip it here.
178.         (asset) => !_config.get('validAppNames').includes(asset.chunk),
179.       )
180.       .map((asset) => {
181.         const sriProps = this.getSriProps(asset.filename);
182. 
183.         return (
184.           <script
185.             async
186.             data-chunk={asset.chunk}
187.             key={asset.url}
188.             src={asset.url}
189.             {...sriProps}
190.           />
191.         );
192.       });
193.   }
194. 
195.   render() {
196.     const {
197.       appState,
198.       chunkExtractor,
199.       component,
200.       htmlDir,
201.       htmlLang,
202.     } = this.props;
203. 
204.     // This must happen before Helmet.rewind() see
205.     // https://github.com/nfl/react-helmet#server-usage for more info.
206.     const content = component ? ReactDOM.renderToString(component) : '';
207.     const head = Helmet.rewind();
208. 
209.     return (
210.       <html lang={htmlLang} dir={htmlDir}>
211.         <head>
212.           {head.title.toComponent()}
213. 
214.           <meta charSet="utf-8" />
215.           <meta name="viewport" content="width=device-width, initial-scale=1" />
216.           {head.meta.toComponent()}
217. 
218.           <link rel="shortcut icon" href={this.getFaviconLink()} />
219.           {head.link.toComponent()}
220.           {this.renderPreLinks()}
221. 
222.           {this.getStyle()}
223.           {this.renderStyles()}
224. 
225.           {head.script.toComponent()}
226.         </head>
227.         <body>
228.           <div id="react-view" dangerouslySetInnerHTML={{ __html: content }} />
229. 
230.           <script
231.             dangerouslySetInnerHTML={{
232.               __html: serialize(appState, { isJSON: true }),
233.             }}
234.             type="application/json"
235.             id="redux-store-state"
236.           />
237.           {chunkExtractor.getRequiredChunksScriptElement()}
238. 
239.           {this.getAnalytics()}
240.           {this.getScript()}
241.           {this.renderAsyncScripts()}
242.         </body>
243.       </html>
244.     );
245.   }
